[TFMDescription("Gets the value from a field on a table or other objects in the context")]
class TFMLogicContextGetFieldFromTable extends TFMLogicContextObject
{
}

Method.Source:
protected void new()
{
    super();

    outputType = TFMLogicContextTypes::None;
    noOfInput = 0;
    categories.add("Data");
}

public Name Name()
{
    return "Get Context Value From Table";
}

public TFMLogicContextTypes outputType()
{
    TFMLogicContextTypes                    ret;
    TFMLogicContextFunctionsDataContract    fdc;
    TFMFlowVariableContextLookupField       fieldName;
    str                                     tableName;
    str                                     tableFieldName;
    str                                     methodName;

    ret = super();
    if (!dataContract)
    {
        return ret;
    }

    fdc = dataContract;

    fieldName = conPeek(fdc.parmParameters(),1);

    [tableName, tableFieldName, methodName] = TFMLogicContext::splitString2TableFieldAndMethod(fieldName);

    if (tableName && tableFieldName && !methodName)
    {
        SysDictField sdf = new SysDictField(tableName2Id(tableName), fieldName2Id(tableName2Id(tableName), tableFieldName));

        ret = this.DictField2ContextType(sdf);
    }

    return ret;
}

public TFMLogicContextTypes DictField2ContextType(SysDictField _sdf)
{
    TFMLogicContextTypes ret; 

    if (_sdf.enumId() == enumNum(NoYes) || (_sdf.typeId() &&  new SysDicTtype(_sdf.typeId()).enumId() == enumNum(NoYes)))
    {
        return TFMLogicContextTypes::Boolean;
    }
    switch (_sdf.baseType())
    {
        case Types::Date :
        case Types::UtcDateTime :
            ret= TFMLogicContextTypes::Date;
            break;
        case Types::Integer :
        case Types::Int64 :
            ret = TFMLogicContextTypes::Integer;
            break;
        case Types::Real :
            ret = TFMLogicContextTypes::Decimal;
            break;
        default :
            ret = TFMLogicContextTypes::String;
            break;
    }
    return ret;
}

public Object process(TFMFlowVariableContextLookupField _fieldName = '')
{
    Map ret = new Map(Types::String, Types::Anytype);
    ret.insert('',context.replaceWithValue(_fieldName, new Map(Types::String, Types::String), false));

    return ret;
}
